import{_ as i,a0 as l,w as o,s as n,ao as m,I as p,x as t,a1 as r,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"使用一块树莓派主板测量圆周率 | LCTT x X-CMD","titleTemplate":false,"description":"使用一块树莓派主板测量圆周率 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用一块树莓派主板测量圆周率 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用一块树莓派主板测量圆周率 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230331.2 ⭐️⭐️ Measure pi with a Raspberry Pi","title":"使用一块树莓派主板测量圆周率","tag":"202304","desc":""},"relativePath":"202304/20230331.2 ⭐️⭐️ Measure pi with a Raspberry Pi.md","filePath":"[post].md"}'),u={name:"202304/20230331.2 ⭐️⭐️ Measure pi with a Raspberry Pi.md"};function d(f,e,h,g,b,T){const a=l("Link");return o(),n("div",null,[e[15]||(e[15]=m('<h1 id="使用一块树莓派主板测量圆周率" tabindex="-1">使用一块树莓派主板测量圆周率 <a class="header-anchor" href="#使用一块树莓派主板测量圆周率" aria-label="Permalink to “使用一块树莓派主板测量圆周率”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202304/13/120203upp4tb199bbhpp59.jpg" alt=""></p><blockquote><p>用你的树莓派制作一个接近完美的圆。</p></blockquote><p>世界各地将 3 月 14 日定为圆周率日。许多人通过在房子周围找到的物体测量圆周率来庆祝圆周率日。我想用我的树莓派 3B 为今年的圆周率日做一些类似的事情。继续阅读以了解我如何使用我的树莓派测量圆周率。</p><p>你需要什么：</p><ul><li>树莓派单板机</li><li>方格纸</li><li>带毫米和厘米测量值的标尺</li><li>笔</li></ul><h3 id="_1、画一个圆" tabindex="-1">1、画一个圆 <a class="header-anchor" href="#_1、画一个圆" aria-label="Permalink to “1、画一个圆”">​</a></h3><p>圆周率是圆的周长与其直径的比值。要计算圆周率，我们需要测量一个完美绘制的圆的周长和直径。幸运的是，树莓派主板上的安装孔足够大，可以使用铅笔或钢笔。我通过一个树莓派板安装孔插入了一根图钉，小心地将针放在一张方格纸上两条线的交点上。</p><p>握住别针，我将一支笔插入对面的安装孔中，并通过将笔绕着别针移动来画一个圆圈。树莓派主板底面的焊点会卡在纸上，但小心点还是可以画好圆圈的。</p><p><img src="https://opensource.com/sites/default/files/2023-03/10000000000003E8000003E8BE7DE71919BB0C82.jpg" alt="Use the Raspberry Pi as a compass to draw a circle."></p><h3 id="_2、把圆分成段" tabindex="-1">2、把圆分成段 <a class="header-anchor" href="#_2、把圆分成段" aria-label="Permalink to “2、把圆分成段”">​</a></h3><p>通过画一条穿过圆心的垂直线将圆分成两半，通过画一条穿过圆心的水平线将圆再次分成四分之一。当我画圆的时候，我把图钉正好放在图画纸上两条线的交点上，这样就很容易找到垂直和水平的中心线。你可以通过在对角线上画一条线来创造一个 “八分” 片。</p><p><img src="https://opensource.com/sites/default/files/2023-03/100000010000028A0000028A0625B218857F031C.webp" alt="Each small wedge is 1/8 of a circle."></p><p>进一步的划分是与尺子的练习。我用尺子找到“四分之一楔形”和“八分之一楔形”任意两个交点的中点，做成一个 1/16 的楔形。你可以使用相同的方法制作越来越小的 1/32 和 1/64 圆的切片。通过非常小心，我还能够在圆的 1/128 处测量出一个非常窄的楔形：</p><p><img src="https://opensource.com/sites/default/files/2023-03/100000000000079E00000514506C8EE5131D886A.webp" alt="If you are careful, you can keep dividing to find 1/128 of a circle."></p><h3 id="_3、估算周长" tabindex="-1">3、估算周长 <a class="header-anchor" href="#_3、估算周长" aria-label="Permalink to “3、估算周长”">​</a></h3><p>我最小的楔形是一个圆的 1/128。如此小的切片，楔形的外弧非常小，我们可以用一条直线来近似它。这实际上不是圆周长的 1/128，但它足够接近，我们可以将其用作一个很好的估计。</p><p><img src="https://opensource.com/sites/default/files/2023-03/10000000000003E8000003E881402FB71F1945FF.jpg" alt="Use the mm measurement on your ruler to measure the outer arc of the 1/128 segment."></p><p>使用我的尺子上的毫米测量值，我测量了我的 1/128 楔形的外弧为 3.8 毫米。这样，我可以估计圆的周长为 3.8 毫米乘以 128，即 486.4 毫米。要转换为厘米，除以十：<strong>48.64cm</strong>。</p><h3 id="_4、计算圆周率" tabindex="-1">4、计算圆周率 <a class="header-anchor" href="#_4、计算圆周率" aria-label="Permalink to “4、计算圆周率”">​</a></h3><p>圆周率的值是圆的周长与其直径的比值。我们在步骤 3 中估算了周长。测量直径是使用尺子测量圆周的简单练习。我的圆是 <strong>15.4cm</strong>。</p><p>现在我们知道了周长和直径，我们可以将圆周率计算为 48.64 除以 15.4，即 <strong>3.158</strong>。这与 pi 的实际值 3.141 相差不远。</p><p>测量圆周率是一项有趣的数学练习！各个年龄段的数学爱好者都可以使用方格纸、笔和尺子等简单工具自行测量圆周率。以一种有趣的新方式使用你的树莓派来绘制圆并独立测量圆周率。这是一个估计值，因为我们将圆上的 1/128 弧近似为一条直线，但这使我们无需太多努力就足够接近了。</p><p>（LCTT 校注：这真是对树莓派的“合理”应用，摔！）</p><p><em>（题图：MJ: Circumference in high resolution, very detailed）</em></p><hr>',26)),p("p",null,[e[1]||(e[1]=t("via: ",-1)),r(a,{href:"https://opensource.com/article/23/3/measure-pi-raspberry-pi"},{default:s(()=>[...e[0]||(e[0]=[t("https://opensource.com/article/23/3/measure-pi-raspberry-pi",-1)])]),_:1})]),p("p",null,[e[6]||(e[6]=t("作者：",-1)),r(a,{href:"https://opensource.com/users/jim-hall"},{default:s(()=>[...e[2]||(e[2]=[t("Jim Hall",-1)])]),_:1}),e[7]||(e[7]=t(" 选题：",-1)),r(a,{href:"https://github.com/lkxed/"},{default:s(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),r(a,{href:"https://github.com/geekpi"},{default:s(()=>[...e[4]||(e[4]=[t("geekpi",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),r(a,{href:"https://github.com/wxy"},{default:s(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),p("p",null,[e[12]||(e[12]=t("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创编译，",-1)),r(a,{href:"https://linux.cn/"},{default:s(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const c=i(u,[["render",d]]);export{_ as __pageData,c as default};
